-- Fixtures descartáveis. Executar SOMENTE em BEGIN ... ROLLBACK.
DO $test$
DECLARE e uuid:=gen_random_uuid(); e2 uuid:=gen_random_uuid(); u uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();p uuid;bp uuid;cfg jsonb;cfg2 jsonb;req jsonb;r jsonb;retry jsonb;k uuid:=gen_random_uuid();oid uuid;paid jsonb;blocked boolean;com uuid;stock numeric;cnt bigint; combo uuid; cb uuid; gr uuid:=gen_random_uuid();mesa uuid;physical uuid;
BEGIN
 INSERT INTO public.empresas(id,nome,status_conta,bloqueado) VALUES(e,'TESTE BAR DIGITAL','aprovado',false),(e2,'TESTE OUTRO BAR','aprovado',false);
 INSERT INTO auth.users(id,email) VALUES(u,'bar-menu-'||u||'@example.invalid'),(u2,'bar-menu-'||u2||'@example.invalid');
 INSERT INTO public.perfis(id,empresa_id,nome,papel,ativo,tipo_acesso) VALUES(u,e,'Operador teste','proprietario',true,'erp'),(u2,e2,'Outro operador','proprietario',true,'erp');
 INSERT INTO public.empresa_modulos(empresa_id,modulo,ativo) VALUES(e,'bar',true),(e2,'bar',true);
 INSERT INTO public.produtos(empresa_id,nome,preco_venda,quantidade_estoque,unidade_comercial) VALUES(e,'Espeto teste',12.5,100,'UN') RETURNING id INTO p;
 SELECT id INTO bp FROM public.bar_produtos WHERE empresa_id=e AND produto_id=p;
 UPDATE public.bar_produtos SET destino_operacional='cozinha',ativo_cardapio=true WHERE id=bp;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 cfg:=public.bar_cardapio_admin('config');
 IF cfg->>'ativo'<>'false' THEN RAISE EXCEPTION 'Cardápio ativado automaticamente';END IF;
 PERFORM public.bar_cardapio_admin('produto',jsonb_build_object('id',bp,'disponivel',true,'descricao','Espeto de teste','categoria','Espetos','foto','data:image/jpeg;base64,/9j/'));
 PERFORM public.bar_cardapio_admin('salvar_config','{"ativo":true,"titulo":"Bar teste","descricao":"Só desta empresa","cor":"#123456","fundo":"#eeeeee","layout":"grade"}');
 r:=public.bar_cardapio_publico('catalogo',cfg->>'token','{}',NULL,repeat('a',64));
 IF r->>'nome'<>'Bar teste' OR r->>'layout'<>'grade' OR jsonb_array_length(r->'produtos')<>1 OR r->'produtos'->0 ? 'quantidade_estoque' THEN RAISE EXCEPTION 'Catálogo incorreto: %',r;END IF;
 req:=jsonb_build_object('nome','Cliente teste','telefone','11999999999','modalidade','entrega','endereco','Rua de teste, 10, Centro','observacao','Tocar campainha','total',25,'itens',jsonb_build_array(jsonb_build_object('bar_produto_id',bp,'quantidade',2,'preco',12.5,'escolhas','[]'::jsonb,'observacao','Sem sal')));
 r:=public.bar_cardapio_publico('confirmar',cfg->>'token',req,k,repeat('a',64));
 IF r->>'numero'<>'1' OR length(r->>'segredo')<>64 THEN RAISE EXCEPTION 'Pedido não confirmado corretamente: %',r;END IF;
 retry:=public.bar_cardapio_publico('confirmar',cfg->>'token',req,k,repeat('a',64));IF retry->>'repetido'<>'true' OR retry->>'segredo'<>r->>'segredo' THEN RAISE EXCEPTION 'Reenvio duplicado';END IF;
 SELECT id INTO oid FROM private.bar_cardapio_pedidos WHERE empresa_id=e AND chave=k;
 IF EXISTS(SELECT 1 FROM public.bar_comandas WHERE empresa_id=e) OR EXISTS(SELECT 1 FROM public.bar_mesas WHERE empresa_id=e) OR EXISTS(SELECT 1 FROM public.vendas WHERE empresa_id=e) OR (SELECT quantidade_estoque FROM public.produtos WHERE id=p)<>100 THEN RAISE EXCEPTION 'Envio público alterou mesas/vendas/estoque';END IF;
 blocked:=false;BEGIN PERFORM public.bar_cardapio_publico('confirmar',cfg->>'token',req||'{"nome":"Outro nome"}',k,repeat('a',64));EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Reenvio alterado aceito';END IF;
 blocked:=false;BEGIN PERFORM public.bar_cardapio_publico('confirmar',cfg->>'token',req||'{"endereco":""}',gen_random_uuid(),repeat('a',64));EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Endereço obrigatório ignorado';END IF;
 blocked:=false;BEGIN PERFORM public.bar_cardapio_publico('confirmar',cfg->>'token',req||'{"total":1}',gen_random_uuid(),repeat('a',64));EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Total adulterado aceito';END IF;
 blocked:=false;BEGIN PERFORM public.bar_cardapio_publico('acompanhar',cfg->>'token','{"segredo":"errado"}',k,repeat('a',64));EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Acompanhamento sem segredo';END IF;
 PERFORM set_config('request.jwt.claim.sub',u2::text,true);cfg2:=public.bar_cardapio_admin('config');
 IF cfg2->>'token'=cfg->>'token' OR jsonb_array_length(cfg2->'produtos')<>0 OR cfg2->>'ativo'<>'false' THEN RAISE EXCEPTION 'Empresas compartilham cardápio';END IF;
 blocked:=false;BEGIN PERFORM public.bar_cardapio_admin('aceitar',jsonb_build_object('id',oid));EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Outra empresa acessou pedido';END IF;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 PERFORM public.bar_cardapio_admin('aceitar',jsonb_build_object('id',oid));
 SELECT comanda_id INTO com FROM private.bar_cardapio_pedidos WHERE id=oid;
 IF com IS NULL OR (SELECT mesa_id FROM public.bar_comandas WHERE id=com) IS NOT NULL OR (SELECT quantidade_estoque FROM public.produtos WHERE id=p)<>98 THEN RAISE EXCEPTION 'Aceite não usou lançamento do Bar sem mesa';END IF;
 PERFORM public.bar_cardapio_admin('aceitar',jsonb_build_object('id',oid));IF (SELECT quantidade_estoque FROM public.produtos WHERE id=p)<>98 THEN RAISE EXCEPTION 'Aceite repetido baixou estoque';END IF;
 blocked:=false;BEGIN PERFORM public.bar_cardapio_admin('finalizar',jsonb_build_object('id',oid,'total',25,'forma','Pix'));EXCEPTION WHEN SQLSTATE 'CX001' THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Recebeu sem caixa BAR';END IF;
 INSERT INTO public.caixas(empresa_id,tipo_caixa,numero,aberto_por,aberto_por_nome) VALUES(e,'BAR',1,u,'Teste');
 PERFORM public.bar_cardapio_admin('estado',jsonb_build_object('id',oid,'estado','pronto'));
 PERFORM public.bar_cardapio_admin('estado',jsonb_build_object('id',oid,'estado','saiu'));
 paid:=public.bar_cardapio_admin('finalizar',jsonb_build_object('id',oid,'total',25,'forma','Pix'));
 IF paid->>'venda_id' IS NULL OR (SELECT status FROM public.bar_comandas WHERE id=com)<>'fechada' THEN RAISE EXCEPTION 'Finalização falhou: %',paid;END IF;
 IF (SELECT count(*) FROM public.vendas WHERE empresa_id=e)<>1 OR (SELECT count(*) FROM public.bar_pagamentos WHERE empresa_id=e)<>1 OR (SELECT quantidade_estoque FROM public.produtos WHERE id=p)<>98 THEN RAISE EXCEPTION 'Pagamento/estoque duplicado';END IF;
 retry:=public.bar_cardapio_admin('finalizar',jsonb_build_object('id',oid,'total',25,'forma','Pix'));IF retry->>'venda_id'<>paid->>'venda_id' THEN RAISE EXCEPTION 'Finalização repetida duplicou venda';END IF;
 r:=public.bar_fiscal_saldo((paid->>'venda_id')::uuid,e);IF r->>'status'<>'fechada' OR (r->>'saldo')::numeric<>0 OR (r->>'total_pago')::numeric<>25 THEN RAISE EXCEPTION 'Contexto fiscal atual incompatível: %',r;END IF;
 IF EXISTS(SELECT 1 FROM public.documentos_fiscais WHERE empresa_id=e) THEN RAISE EXCEPTION 'Emitiu fiscal automaticamente';END IF;
 IF EXISTS(SELECT 1 FROM public.bar_mesas WHERE empresa_id=e) THEN RAISE EXCEPTION 'Criou mesas artificiais';END IF;
 IF md5(pg_get_functiondef('public.bar_comanda_pagar_valor(uuid,numeric,jsonb,uuid,numeric,numeric,numeric)'::regprocedure))<>'e3701d39eedc890f8d732bcf9aef4285' THEN RAISE EXCEPTION 'Alterou pagamento original';END IF;
 IF has_function_privilege('anon','public.bar_cardapio_admin(text,jsonb)','execute') OR has_function_privilege('anon','public.bar_cardapio_publico(text,text,jsonb,uuid,text)','execute') OR has_table_privilege('authenticated','private.bar_cardapio_pedidos','select') THEN RAISE EXCEPTION 'Privilégios excessivos';END IF;
 -- Produtos compostos mantêm as escolhas e a baixa física já usada pelo Bar.
 INSERT INTO public.produtos(empresa_id,nome,preco_venda,quantidade_estoque,unidade_comercial) VALUES(e,'Combo digital teste',30,0,'UN') RETURNING id INTO combo;
 SELECT id INTO cb FROM public.bar_produtos WHERE empresa_id=e AND produto_id=combo;
 UPDATE public.bar_produtos SET tipo='composto',destino_operacional='sem_destino',ativo_cardapio=true WHERE id=cb;
 INSERT INTO public.bar_produto_grupos(id,empresa_id,bar_produto_id,nome,quantidade_escolhas) VALUES(gr,e,cb,'Escolha o espeto',1);
 INSERT INTO public.bar_produto_grupo_opcoes(empresa_id,grupo_id,produto_id) VALUES(e,gr,p);
 PERFORM public.bar_cardapio_admin('produto',jsonb_build_object('id',cb,'disponivel',true));
 req:=jsonb_set(req,'{itens}',jsonb_build_array(jsonb_build_object('bar_produto_id',cb,'quantidade',1,'preco',30,'escolhas',jsonb_build_array(jsonb_build_object('grupo_id',gr,'produto_id',p)))))||'{"total":30,"modalidade":"retirada"}'::jsonb;
 k:=gen_random_uuid();r:=public.bar_cardapio_publico('confirmar',cfg->>'token',req,k,repeat('a',64));
 blocked:=false;BEGIN PERFORM public.bar_cardapio_publico('confirmar',cfg->>'token',jsonb_set(req,'{itens,0,escolhas}','[]'),gen_random_uuid(),repeat('a',64));EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Combo sem escolha aceito';END IF;
 SELECT id INTO oid FROM private.bar_cardapio_pedidos WHERE empresa_id=e AND chave=k;
 DROP TABLE pg_temp._bar_itens_pedido,pg_temp._bar_escolhas_por_item,pg_temp._bar_baixas_por_item;
 PERFORM public.bar_cardapio_admin('aceitar',jsonb_build_object('id',oid));
 IF (SELECT quantidade_estoque FROM public.produtos WHERE id=p)<>97 OR NOT EXISTS(SELECT 1 FROM public.bar_pedidos_itens_escolhas WHERE empresa_id=e AND grupo_id=gr AND produto_id=p) THEN RAISE EXCEPTION 'Escolha não virou consumo físico correto';END IF;
 -- Regressão: mesa presencial continua pelo recebimento original, sem usar o novo adaptador.
 INSERT INTO public.bar_mesas(empresa_id,numero) VALUES(e,1) RETURNING id INTO mesa;
 PERFORM public.bar_mesa_abrir(mesa,0);
 SELECT comanda_atual_id INTO physical FROM public.bar_mesas WHERE id=mesa;
 DROP TABLE pg_temp._bar_itens_pedido,pg_temp._bar_escolhas_por_item,pg_temp._bar_baixas_por_item;
 PERFORM public.bar_pedido_enviar(physical,jsonb_build_array(jsonb_build_object('bar_produto_id',bp,'quantidade',1)),gen_random_uuid());
 PERFORM public.bar_comanda_pagar_valor(physical,12.5,'[{"forma_pagamento":"Dinheiro","valor":12.5}]',gen_random_uuid());
 IF (SELECT status FROM public.bar_mesas WHERE id=mesa)<>'livre' THEN RAISE EXCEPTION 'Regressão no fechamento da mesa presencial';END IF;
 IF NOT has_schema_privilege('service_role','private','usage') OR NOT has_schema_privilege('authenticated','private','usage') THEN RAISE EXCEPTION 'Bridge sem acesso ao schema privado';END IF;
END $test$;
SET CONSTRAINTS ALL IMMEDIATE;
SET LOCAL ROLE authenticated;
SELECT jsonb_typeof(public.bar_cardapio_admin('listar')->'pedidos') AS authenticated_access;
RESET ROLE;
SELECT 'PASS: catálogo por empresa, endereço, reenvio, privacidade, aceite, caixa BAR, venda única, saldo fiscal e ausência de mesas artificiais/emissão automática' resultado;
